parameters.jsCode:
// Format SW4 response for Router
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json;
const inputData = $('When Executed by Another Workflow').first().json;

// If AI returned structured response, use it
if (aiOutput.workflow === 'SW4') {
  return [{
    json: aiOutput
  }];
}

// Otherwise, build structured response
let response = {
  workflow: 'SW4',
  operation: 'unknown',
  success: true,
  data: null,
  summary: '',
  error: null
};

// Try to parse AI output
if (typeof aiOutput === 'string') {
  try {
    const parsed = JSON.parse(aiOutput);
    response = { ...response, ...parsed };
  } catch (e) {
    response.summary = aiOutput;
  }
} else if (typeof aiOutput === 'object') {
  response = { ...response, ...aiOutput };
}

// Infer operation type from query if not set
const query = (inputData.query || '').toLowerCase();
if (!response.operation || response.operation === 'unknown') {
  if (query.includes('list users') || query.includes('show team')) {
    response.operation = 'list_users';
  } else if (query.includes('get user') || inputData.user_id) {
    response.operation = 'get_user';
  } else if (query.includes('find user') || query.includes('search')) {
    response.operation = 'search_users';
  } else if (query.includes('list views') || query.includes('show views')) {
    response.operation = 'list_views';
  } else if (query.includes('integrations')) {
    response.operation = 'list_integrations';
  } else if (query.includes('custom field') || query.includes('fields')) {
    response.operation = 'list_custom_fields';
  } else if (query.includes('exist') || query.includes('valid')) {
    response.operation = 'validate';
  }
}

return [{
  json: response
}];

// Log API call to Supabase
const items = $input.all();
const inputData = $('When Executed by Another Workflow').first().json;
const response = items[0].json;

const logEntry = {
  workflow_id: 'SW4',
  run_id: $execution.id,
  node_name: 'SW4_AI_Agent',
  direction: 'response',
  method: response.operation || 'resource_discovery',
  url: `${$vars.GORGIAS_BASE_URL}/api/${response.operation?.includes('user') ? 'users' : response.operation?.includes('view') ? 'views' : response.operation?.includes('integration') ? 'integrations' : 'custom-fields'}`,
  status_code: response.success ? 200 : 500,
  request_body: JSON.stringify(inputData),
  response_body: JSON.stringify(response.data || response.summary),
  error_message: response.error || null,
  actor_user: inputData.user || null,
  channel: inputData.channel || null,
  thread_ts: inputData.thread_ts || null,
  ticket_id: null,
  tags: [],
  duration_ms: null,
  extra: JSON.stringify({
    operation: response.operation
  })
};

return [{
  json: logEntry
}];
